#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_TRIGONOMETRY_H
#include <stdio.h>
#include <stdint.h>
#define P(v) printf("%lld", (long long)(v))
int main(void){
  long long A[] = {0, 1, -1, 0x8000, 30LL<<16, 45LL<<16, 60LL<<16, 89LL<<16, 90LL<<16, 91LL<<16, 135LL<<16, 180LL<<16, -(90LL<<16), -(180LL<<16), 270LL<<16, 359LL<<16, 360LL<<16, -(360LL<<16), (720LL<<16)+12345, -(1000LL<<16)-7, 0x123456789LL, -0x123456789LL, 1LL<<40};
