  printf("VECTORS\n");
  for (unsigned i = 0; i < sizeof V / sizeof *V; i++) { FT_Vector v = {V[i][0], V[i][1]}; FT_Fixed len = -1; FT_Angle an = -1; FT_Vector_Polarize(&v, &len, &an);
