  printf("ROTATIONS\n");
  for (unsigned i = 0; i < sizeof V / sizeof *V; i++) for (unsigned j = 0; j < 4; j++) { FT_Vector v = {V[i][0], V[i][1]}; FT_Vector_Rotate(&v, R[j]);
    printf("    {"); P(V[i][0]); printf(", "); P(V[i][1]); printf(", "); P(R[j]); printf(", "); P(v.x); printf(", "); P(v.y); printf("},\n"); }
