  printf("POLAR\n");
  for (unsigned i = 0; i < 5; i++) for (unsigned j = 0; j < 4; j++) { FT_Vector v; FT_Vector_From_Polar(&v, L[i], PA[j]);
    printf("    {"); P(L[i]); printf(", "); P(PA[j]); printf(", "); P(v.x); printf(", "); P(v.y); printf("},\n"); }
  long long D[][2] = {{0,10LL<<16},{10LL<<16,0},{0,190LL<<16},{0,-(190LL<<16)},{350LL<<16,10LL<<16},{1LL<<40,5},{-(1LL<<40),1LL<<40}};
